declare module 'react-speech-kit' {  export interface SpeechSynthesisVoice {    name: string;    lang: string;    default: boolean;    localService: boolean;    voiceURI: string;  }  export interface SpeechSynthesisOptions {    text: string;    voice?: SpeechSynthesisVoice;    rate?: number;    pitch?: number;    volume?: number;    onEnd?: () => void;    onError?: (error: Error) => void;  }  export interface UseSpeechSynthesisReturn {    speak: (options: SpeechSynthesisOptions) => void;    cancel: () => void;    speaking: boolean;    supported: boolean;    voices: SpeechSynthesisVoice[];  }  export function useSpeechSynthesis(): UseSpeechSynthesisReturn;  export interface UseSpeechRecognitionReturn {    listen: (options?: { interimResults?: boolean; lang?: string }) => void;    stop: () => void;    listening: boolean;    supported: boolean;  }  export function useSpeechRecognition(options?: {    onResult?: (result: string) => void;    onEnd?: () => void;    onError?: (error: Error) => void;  }): UseSpeechRecognitionReturn;}